SPECIAL_CODES = frozenset(row[0] for row in _RECIPES.values())

def symbol_recipe(row):
    if row['code'] not in SPECIAL_CODES:
        return ('unicode', chr(row['code']))
    entry = _RECIPES.get(row['samples_sha256'])
    if entry is None or entry[0] != row['code']:
        raise FormatError('Unknown native GSchar symbol; retain the native glyph')
    return (entry[1], entry[2])
